package com.smartlibrary.algorithms.dp;import com.smartlibrary.model.Book;import java.util.*;
public final class BookKnapsack {private BookKnapsack(){}public record Plan(List<Book> books,int minutes,int value){}public static Plan solve(List<Book> books,int budget){if(budget<0)throw new IllegalArgumentException("Budget must be non-negative");int n=books.size();if(n>25)throw new IllegalArgumentException("Bitmask planner supports at most 25 books");int[] dp=new int[budget+1];int[][] take=new int[n+1][budget+1];for(int i=1;i<=n;i++){Book b=books.get(i-1);for(int w=budget;w>=b.getReadingMinutes();w--){int cand=dp[w-b.getReadingMinutes()]+b.getLearningValue();if(cand>dp[w]){dp[w]=cand;take[i][w]=1;}}}List<Book> chosen=new ArrayList<>();int w=budget;for(int i=n;i>=1;i--){Book b=books.get(i-1);if(take[i][w]==1){chosen.add(b);w-=b.getReadingMinutes();}}Collections.reverse(chosen);int mins=chosen.stream().mapToInt(Book::getReadingMinutes).sum();return new Plan(chosen,mins,chosen.stream().mapToInt(Book::getLearningValue).sum());}}
